/**
 * @name Server-Side Request Forgery (SSRF)
 * @description Fetching data from a user-controlled URL can lead to SSRF.
 * @kind path-problem
 * @problem.severity error
 * @id py/ssrf
 * @tags security
 *       external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SsrfConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // urllib.request.urlopen(url)
    sink = API::moduleImport("urllib").getMember("request").getMember("urlopen").getACall().getArg(0)
    or
    // urllib.urlopen(url) - legacy
    sink = API::moduleImport("urllib").getMember("urlopen").getACall().getArg(0)
    or
    // requests.get/post/etc (url) - not in deps but good to check
    sink = API::moduleImport("requests").getMember(["get", "post", "put", "delete", "head", "patch", "request"]).getACall().getArg(0)
  }
}

module SsrfFlow = TaintTracking::Global<SsrfConfig>;
import SsrfFlow::PathGraph

from SsrfFlow::PathNode source, SsrfFlow::PathNode sink
where SsrfFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential SSRF from $@.", source.getNode(), "user input"

/**
 * @name URL to Path Traversal
 * @description Tracing flow from URL parsing to file opening, which might indicate path traversal via file URIs.
 * @kind path-problem
 * @problem.severity error
 * @id py/url-to-path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs
import semmle.python.Concepts

module UrlToPathConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source: Output of urllib.parse functions
    source = API::moduleImport("urllib").getMember("parse").getMember(["urlparse", "urlsplit", "unquote", "unquote_plus"]).getACall()
    or
    source = API::moduleImport("urllib").getMember("parse").getMember(["urljoin"]).getACall()
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: File opening or path manipulation
    sink = any(FileSystemAccess fa).getAPathArgument()
    or
    sink = API::moduleImport("os").getMember("path").getMember(["join", "abspath", "normpath"]).getACall().getArg(_)
  }
}

module UrlToPathFlow = TaintTracking::Global<UrlToPathConfig>;
import UrlToPathFlow::PathGraph

from UrlToPathFlow::PathNode source, UrlToPathFlow::PathNode sink
where UrlToPathFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from URL parsing at $@.", source.getNode(), "URL source"
